if (!usuario || !usuario.password_hash) {
  return [{ json: { match: false, id: null, email: body.email || null, username: null, role: null } }];
}

const hashCalculado = crypto.scryptSync(password, usuario.password_salt, 64);
const hashAlmacenado = Buffer.from(usuario.password_hash, 'hex');

let match = false;
if (hashCalculado.length === hashAlmacenado.length) {
  match = crypto.timingSafeEqual(hashCalculado, hashAlmacenado);
}

return [{ json: { match, id: usuario.id, email: usuario.email, username: usuario.username, role: usuario.role } }];

const crypto = require('crypto');
