const crypto = require('crypto');
const filas = $input.all();
const body = $('Webhook Reset1').first().json.body || {};
const password = body.password || '';

const usuario = filas.length > 0 && filas[0].json && filas[0].json.id ? filas[0].json : null;

let error = null;
if (!usuario) {
  error = 'El enlace de recuperación no es válido o ya expiró.';
} else if (password.length < 8) {
  error = 'La contraseña debe tener al menos 8 caracteres.';
}

if (error) {
  return [{ json: { valido: false, error } }];
}

const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.scryptSync(password, salt, 64).toString('hex');

return [{
  json: {
    valido: true,
    error: null,
    id: usuario.id,
    email: usuario.email,
    password_hash: hash,
    password_salt: salt
  }
}];

function normalizar(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, '').toUpperCase();
}

function getVal(fila, ...posiblesNombres) {
  for (const nombreBuscado of posiblesNombres) {
    const claveReal = Object.keys(fila).find(k => normalizar(k) === normalizar(nombreBuscado));
    if (claveReal && fila[claveReal]) return fila[claveReal];
  }
  return '';
}

const texto = $json.data;
const lineas = texto.split(/\r?\n/).filter(l => l.trim() !== "");
const headers = lineas[0].split(";").map(h => h.trim().toUpperCase());

const vistos = new Set();
const output = [];

for (let i = 1; i < lineas.length; i++) {
  const valores = lineas[i].split(";");
  if (valores.length < headers.length) continue;

  const fila = {};
  headers.forEach((h, idx) => { fila[h] = (valores[idx] || "").trim(); });

  const fecha = getVal(fila, "FECHA");
  const departamento = getVal(fila, "DEPARTAMENTO");
  if (!fecha || !departamento) continue;

  const codigoVia = getVal(fila, "CODIGO_VIA", "CODIGO_VÍA", "CODIGO VIA");
  const kilometro = getVal(fila, "KILOMETRO");
  const hora = getVal(fila, "HORA");

  const clave = [fecha, hora, departamento, codigoVia, kilometro].join("|");
  if (vistos.has(clave)) continue;
  vistos.add(clave);

  output.push({
    json: {
      fecha_corte: getVal(fila, "FECHA_CORTE") || null,
      fecha_siniestro: fecha,
      hora_siniestro: hora,
      departamento,
      codigo_via: codigoVia,
      kilometro,
      modalidad: getVal(fila, "MODALIDAD") || null,
      fallecidos: parseInt(getVal(fila, "FALLECIDOS")) || 0,
      heridos: parseInt(getVal(fila, "HERIDOS")) || 0
    }
  });
}

return output;

