  }
};

// Hash determinístico en JS puro (sin módulos nativos, n8n bloquea 'crypto').
// Misma entrada => siempre el mismo hash.
function hashPar(str, seed) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return ((h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0'));
}

const items = $input.first().json.incidents || [];

return items.map(inc => {
  const coords = inc.geometry?.coordinates || [];
  const primerPunto = coords[0] || [null, null]; // [lon, lat]

  // ID determinístico: mismo incidente activo => mismo ID siempre.
  // Se basa en datos que no cambian mientras el incidente sigue activo
  // (categoría + punto de inicio del tramo + hora de inicio reportada por TomTom).
  const claveEstable = [
    inc.properties?.iconCategory,
    primerPunto[0],
    primerPunto[1],
    inc.properties?.startTime
  ].join('|');
  const hash = hashPar(claveEstable, 0); // 16 caracteres hex
  const incidentId = 'TTI-' + hash.slice(0,8) + '-' + hash.slice(8,12) + '-' + hash.slice(12,16);

  return {
    json: {
      incident_id: incidentId,
      icon_category: inc.properties?.iconCategory ?? null,
      descripcion: inc.properties?.events?.[0]?.description || null,
      latitude: primerPunto[1],
      longitude: primerPunto[0],
      start_time: inc.properties?.startTime || null,
      end_time: inc.properties?.endTime || null,
      raw_properties: JSON.stringify(inc.properties || {})
    }
  };
});

